import React, { useState, useEffect } from 'react';
import { Sparkles, Loader2, RefreshCw } from 'lucide-react';
import { getCryptoInsights } from '../services/geminiService';
import { MOCK_ASSETS } from '../constants';

const CryptoAI: React.FC = () => {
  const [insight, setInsight] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const fetchInsight = async () => {
    setLoading(true);
    const result = await getCryptoInsights(MOCK_ASSETS);
    setInsight(result);
    setLoading(false);
  };

  useEffect(() => {
    // Optionally fetch on mount, but better to trigger on interaction
    // to save tokens/API calls in a real app.
  }, []);

  return (
    <div className="bg-gradient-to-r from-emerald-500/10 via-[#161616] to-[#161616] border border-emerald-500/20 rounded-3xl p-6 shadow-xl relative overflow-hidden group">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 relative z-10">
        <div className="flex items-start space-x-4">
          <div className="bg-emerald-500/20 p-3 rounded-2xl">
            <Sparkles className="text-emerald-500" size={24} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-white flex items-center space-x-2">
              <span>CryptoAI Insights</span>
              <span className="text-[10px] bg-emerald-500 text-black px-2 py-0.5 rounded-full font-bold uppercase tracking-widest">Beta</span>
            </h3>
            <div className="mt-2 text-gray-400 text-sm max-w-2xl min-h-[3rem]">
              {loading ? (
                <div className="flex items-center space-x-2 text-emerald-500/70">
                  <Loader2 className="animate-spin" size={16} />
                  <span>Analyzing portfolio dynamics and market signals...</span>
                </div>
              ) : (
                insight || "Analyze your portfolio with Gemini 3 Pro for real-time market insights and personalized strategy advice."
              )}
            </div>
          </div>
        </div>

        <button 
          onClick={fetchInsight}
          disabled={loading}
          className={`flex items-center space-x-2 px-6 py-3 rounded-2xl font-bold text-sm transition-all whitespace-nowrap ${
            loading 
              ? 'bg-[#1a1a1a] text-gray-500 cursor-not-allowed' 
              : 'bg-emerald-500 text-black hover:bg-emerald-400 shadow-lg shadow-emerald-500/20 hover:scale-105 active:scale-95'
          }`}
        >
          {loading ? <RefreshCw className="animate-spin" size={18} /> : <Sparkles size={18} />}
          <span>{insight ? 'Regenerate Analysis' : 'Generate Analysis'}</span>
        </button>
      </div>

      {/* Decorative Glow */}
      <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/5 blur-[80px] rounded-full -mr-20 -mt-20"></div>
    </div>
  );
};

export default CryptoAI;

import { GoogleGenAI } from "@google/genai";
import { Asset } from "../types";

// Always use process.env.API_KEY directly for initialization as per guidelines
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getCryptoInsights = async (assets: Asset[]): Promise<string> => {
  const assetSummary = assets.map(a => `${a.name}: ${a.quantity} units, current value $${a.value}`).join(', ');
  const prompt = `Act as a senior crypto analyst. I have the following portfolio: ${assetSummary}. Based on current market trends, provide a concise 3-sentence analysis of this portfolio and one actionable piece of advice. Keep the tone professional and modern. Do not use markdown headers.`;

  try {
    const response = await ai.models.generateContent({
      // Using gemini-3-pro-preview for complex portfolio reasoning tasks
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });
    // Use .text property to extract output string
    return response.text || "Unable to generate insights at this time.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "The AI assistant is currently recharging. Please try again in a few moments.";
  }
};

