import { GoogleGenAI } from "@google/genai";
import { Asset, Transaction } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getCryptoInsights = async (assets: Asset[]): Promise<string> => {
  const assetSummary = assets.map(a => `${a.name}: ${a.quantity} units, current value $${a.value}`).join(', ');
  const prompt = `Act as a senior crypto analyst. I have the following portfolio: ${assetSummary}. Based on current market trends, provide a concise 3-sentence analysis of this portfolio and one actionable piece of advice. Keep the tone professional and modern. Do not use markdown headers.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });
    return response.text || "Unable to generate insights at this time.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "The AI assistant is currently recharging. Please try again in a few moments.";
  }
};

export const auditTransactions = async (transactions: Transaction[]): Promise<string> => {
  const txSummary = transactions.map(t => `${t.type} of ${t.asset} (${t.fiatValue}) - Status: ${t.status}`).join(' | ');
  const prompt = `Act as a crypto tax and forensic auditor. Analyze these recent transactions: ${txSummary}. Identify potential tax implications or operational risks. Provide a very concise 2-sentence summary of the overall health of these activities. Do not use markdown headers.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
    });
    return response.text || "Audit data unavailable.";
  } catch (error) {
    console.error("Gemini Audit Error:", error);
    return "Forensic engine is offline. Using local rule-sets.";
  }
};

