import React, { useState } from 'react';
import { MOCK_TRANSACTIONS } from '../constants';
import { 
  FileSearch, 
  ExternalLink, 
  AlertCircle, 
  CheckCircle2, 
  Clock, 
  Sparkles,
  ShieldAlert,
  Download,
  Filter
} from 'lucide-react';
import { auditTransactions } from '../services/geminiService';

const HistoryView: React.FC = () => {
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [isAuditing, setIsAuditing] = useState(false);

  const runAudit = async () => {
    setIsAuditing(true);
    const result = await auditTransactions(MOCK_TRANSACTIONS);
    setAuditResult(result);
    setIsAuditing(false);
  };

  const getCategoryColor = (category: string) => {
    const cat = category.toLowerCase();
    if (cat.includes('income') || cat.includes('salary')) return 'bg-emerald-500';
    if (cat.includes('disposal')) return 'bg-gray-500';
    if (cat.includes('swap')) return 'bg-blue-500';
    if (cat.includes('yield') || cat.includes('stake')) return 'bg-purple-500';
    return 'bg-emerald-500'; // Default
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* AI Forensic Header */}
      <section className="bg-gradient-to-r from-[#161616] to-[#0d0d0d] border border-[#222] rounded-[2rem] p-8 shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/5 blur-[80px] rounded-full" aria-hidden="true"></div>
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex items-center space-x-4">
            <div className="w-14 h-14 bg-emerald-500/10 rounded-2xl flex items-center justify-center border border-emerald-500/20 shadow-lg shadow-emerald-500/5">
              <FileSearch size={28} className="text-emerald-500" aria-hidden="true" />
            </div>
            <div>
              <h2 className="text-2xl font-bold tracking-tight">Smart History Audit</h2>
              <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] mt-1">AI-Powered Compliance & Forensics</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
             <button className="bg-[#1a1a1a] border border-[#2a2a2a] p-3 rounded-xl hover:bg-[#222] transition-all text-gray-400 focus-visible:ring-2 focus-visible:ring-emerald-500 outline-none" aria-label="Filter history">
                <Filter size={18} aria-hidden="true" />
             </button>
             <button className="bg-[#1a1a1a] border border-[#2a2a2a] p-3 rounded-xl hover:bg-[#222] transition-all text-gray-400 focus-visible:ring-2 focus-visible:ring-emerald-500 outline-none" aria-label="Export history">
                <Download size={18} aria-hidden="true" />
             </button>
             <button 
                onClick={runAudit}
                disabled={isAuditing}
                className="bg-emerald-500 text-black px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-400 transition-all flex items-center space-x-2 shadow-lg shadow-emerald-500/10 active:scale-95 disabled:opacity-50"
             >
                {isAuditing ? <Clock className="animate-spin" size={14} /> : <Sparkles size={14} />}
                <span>{isAuditing ? 'Auditing...' : 'Run Forensic Audit'}</span>
             </button>
          </div>
        </div>

        {auditResult && (
          <div className="mt-8 bg-emerald-500/5 border border-emerald-500/20 rounded-2xl p-6 animate-in slide-in-from-top-2 duration-500" aria-live="polite">
            <div className="flex items-start space-x-3">
              <ShieldAlert className="text-emerald-500 mt-0.5 shrink-0" size={16} aria-hidden="true" />
              <p className="text-xs text-emerald-100 leading-relaxed font-medium">{auditResult}</p>
            </div>
          </div>
        )}
      </section>

      {/* Main History Table */}
      <section className="bg-[#161616] border border-[#222] rounded-[2rem] p-8 shadow-2xl overflow-hidden" aria-labelledby="history-title">
        <div className="flex justify-between items-center mb-8">
           <h3 id="history-title" className="text-lg font-bold tracking-tight">Activity Log</h3>
           <div className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Showing last 25 operations</div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="text-gray-500 text-[10px] uppercase tracking-[0.2em] border-b border-[#222]">
              <tr>
                <th scope="col" className="pb-6 font-black">Date / ID</th>
                <th scope="col" className="pb-6 font-black">Type</th>
                <th scope="col" className="pb-6 font-black">Asset</th>
                <th scope="col" className="pb-6 font-black">Value</th>
                <th scope="col" className="pb-6 font-black">AI Category</th>
                <th scope="col" className="pb-6 font-black">Status</th>
                <th scope="col" className="pb-6 font-black text-right">Explorer</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#222]">
              {MOCK_TRANSACTIONS.map((tx) => (
                <tr key={tx.id} className="group hover:bg-white/[0.02] transition-colors">
                  <td className="py-6">
                    <div className="text-xs font-bold text-gray-200">{tx.date}</div>
                    <div className="text-[9px] font-mono text-gray-600 uppercase mt-1">#TX-{tx.id.padStart(4, '0')}</div>
                  </td>
                  <td className="py-6">
                    <span className={`px-2.5 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
                      tx.type === 'Swap' ? 'bg-blue-500/10 text-blue-400' :
                      tx.type === 'Stake' ? 'bg-purple-500/10 text-purple-400' :
                      tx.type === 'Receive' ? 'bg-emerald-500/10 text-emerald-400' :
                      'bg-gray-500/10 text-gray-400'
                    }`}>
                      {tx.type}
                    </span>
                  </td>
                  <td className="py-6 font-mono text-sm font-bold text-gray-300">{tx.asset}</td>
                  <td className="py-6">
                    <div className="text-sm font-mono font-bold text-white">{tx.amount}</div>
                    <div className="text-[9px] font-mono text-gray-500">{tx.fiatValue}</div>
                  </td>
                  <td className="py-6">
                    <div className="flex items-center space-x-2">
                       <div className={`w-1.5 h-1.5 rounded-full ${getCategoryColor(tx.aiCategory)}`} aria-hidden="true"></div>
                       <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">{tx.aiCategory}</span>
                    </div>
                  </td>
                  <td className="py-6">
                    <div className="flex items-center space-x-2">
                      {tx.status === 'Success' && <CheckCircle2 size={14} className="text-emerald-500" aria-hidden="true" />}
                      {tx.status === 'Pending' && <Clock size={14} className="text-amber-500 animate-pulse" aria-hidden="true" />}
                      {tx.status === 'Failed' && <AlertCircle size={14} className="text-rose-500" aria-hidden="true" />}
                      <span className={`text-[10px] font-black uppercase tracking-widest ${
                        tx.status === 'Success' ? 'text-emerald-500' :
                        tx.status === 'Pending' ? 'text-amber-500' :
                        'text-rose-500'
                      }`}>
                        {tx.status}
                      </span>
                    </div>
                  </td>
                  <td className="py-6 text-right">
                    <button 
                      aria-label="View on block explorer"
                      className="text-gray-600 hover:text-emerald-500 transition-colors p-2 hover:bg-[#1a1a1a] rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-emerald-500"
                    >
                      <ExternalLink size={16} aria-hidden="true" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {/* Tax Info Card */}
      <div className="bg-[#161616]/40 border border-[#222] rounded-2xl p-6 flex items-start space-x-4">
        <div className="w-10 h-10 rounded-xl bg-blue-500/10 flex items-center justify-center border border-blue-500/20 shrink-0">
          <Sparkles size={20} className="text-blue-500" aria-hidden="true" />
        </div>
        <div>
          <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Audit Insights</h4>
          <p className="text-xs text-gray-500 leading-relaxed uppercase tracking-wider">
            All transaction tags are generated based on block-explorer heuristics. These categories are for informational purposes and should be verified with a qualified tax professional for official reporting.
          </p>
        </div>
      </div>
    </div>
  );
};

