import React, { useState, useMemo } from 'react';
import { MOCK_ORDER_BOOK, MOCK_RECENT_TRADES } from '../constants';
import { 
  ChevronDown, 
  ArrowUpRight, 
  TrendingUp, 
  Maximize2, 
  Zap, 
  MousePointer2, 
  PenTool, 
  Hash, 
  Eye,
  Settings2,
  Lock,
  Unlock,
  Activity
} from 'lucide-react';

const ProTradingView: React.FC = () => {
  const [orderType, setOrderType] = useState<'limit' | 'market' | 'stop'>('limit');
  const [side, setSide] = useState<'buy' | 'sell'>('buy');
  const [price, setPrice] = useState('3208.93');

  const candles = useMemo(() => [...Array(44)].map((_, i) => {
    const isUp = Math.random() > 0.48;
    const base = 20 + Math.random() * 50;
    const bodySize = 5 + Math.random() * 25;

    let open, close;
    if (isUp) {
      open = base;
      close = base + bodySize;
    } else {
      open = base + bodySize;
      close = base;
    }

    const high = Math.max(open, close) + (Math.random() * 10);
    const low = Math.min(open, close) - (Math.random() * 10);

    return { isUp, high, low, open, close };
  }), []);

