          <Sparkles className="text-emerald-500" size={16} aria-hidden="true" />
          <h3 id="ai-intel-title" className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400">AI Intelligence</h3>
        </div>
        <button aria-label="About AI Intelligence" className="text-zinc-600 cursor-help hover:text-emerald-500 transition-colors outline-none">
          <Info size={14} aria-hidden="true" />
        </button>
      </div>

      <div className="space-y-5">
        <div 
          className="bg-[#0d0d0d] border border-white/[0.03] p-5 rounded-2xl min-h-[120px] relative transition-all group-hover:border-emerald-500/20 flex flex-col justify-center"
          aria-live="polite"
        >
          {loading ? (
            <div className="flex flex-col items-center justify-center space-y-3">
              <Loader2 className="animate-spin text-emerald-500" size={20} aria-hidden="true" />
              <p className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.2em] animate-pulse">Scanning market...</p>
            </div>
          ) : (
            <p className="text-xs leading-relaxed text-zinc-400 font-medium">
