          onClick={fetchInsight}
          disabled={loading}
          aria-label={insight ? 'Refresh market intel' : 'Analyze current portfolio'}
          className={`w-full flex items-center justify-center space-x-2 py-3.5 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] transition-all outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/50 ${
            loading 
              ? 'bg-zinc-800 text-zinc-600 cursor-not-allowed' 
