          {loading ? <RefreshCw className="animate-spin" size={14} aria-hidden="true" /> : <Sparkles size={14} className="text-emerald-500" aria-hidden="true" />}
          <span>{insight ? 'Refresh Intel' : 'Analyze Portfolio'}</span>
        </button>
      </div>

      <div className="absolute -right-10 -bottom-10 w-32 h-32 bg-emerald-500/5 blur-[40px] rounded-full pointer-events-none" aria-hidden="true"></div>
    </section>
  );
};

