import React, { useState } from 'react';
import { MOCK_TRANSACTIONS } from '../constants';
import { 
  FileSearch, 
  ExternalLink, 
  AlertCircle, 
  CheckCircle2, 
  Clock, 
  Sparkles,
  ShieldAlert,
  Download,
  Filter
} from 'lucide-react';
import { auditTransactions } from '../services/geminiService';

const HistoryView: React.FC = () => {
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [isAuditing, setIsAuditing] = useState(false);

  const runAudit = async () => {
    setIsAuditing(true);
    const result = await auditTransactions(MOCK_TRANSACTIONS);
    setAuditResult(result);
    setIsAuditing(false);
  };

  const getCategoryColor = (category: string) => {
    const cat = category.toLowerCase();
    if (cat.includes('income')) return 'bg-emerald-500';
    if (cat.includes('swap')) return 'bg-blue-500';
    if (cat.includes('yield')) return 'bg-purple-500';
    return 'bg-zinc-500';
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* AI Forensic Header */}
      <section className="bg-zinc-900/40 border border-white/5 rounded-[2.2rem] p-8 shadow-xl backdrop-blur-md relative overflow-hidden group">
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex items-center space-x-4">
            <div className="w-1.5 h-10 bg-emerald-500 rounded-full"></div>
            <div>
              <h2 className="text-2xl font-bold tracking-tight text-white">Smart History Audit</h2>
              <p className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em] mt-1">AI-Powered Compliance</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
             <button className="bg-zinc-800 border border-white/5 p-3 rounded-xl hover:bg-zinc-700 transition-all text-zinc-400">
                <Filter size={18} />
             </button>
             <button className="bg-zinc-800 border border-white/5 p-3 rounded-xl hover:bg-zinc-700 transition-all text-zinc-400">
                <Download size={18} />
             </button>
             <button 
                onClick={runAudit}
                disabled={isAuditing}
                className="bg-emerald-500 text-black px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-emerald-400 transition-all flex items-center space-x-2 shadow-lg shadow-emerald-500/10 active:scale-95 disabled:opacity-50"
             >
                {isAuditing ? <Clock className="animate-spin" size={14} /> : <Sparkles size={14} />}
                <span>{isAuditing ? 'AUDITING...' : 'RUN FORENSIC AUDIT'}</span>
             </button>
          </div>
        </div>

        {auditResult && (
          <div className="mt-8 bg-emerald-500/5 border border-emerald-500/20 rounded-2xl p-6 animate-in slide-in-from-top-2 duration-500">
            <div className="flex items-start space-x-3">
              <ShieldAlert className="text-emerald-500 mt-0.5 shrink-0" size={16} />
              <p className="text-xs text-emerald-100 leading-relaxed font-medium italic">{auditResult}</p>
            </div>
          </div>
        )}
      </section>

      {/* Main History Table */}
      <section className="bg-zinc-900/40 border border-white/5 rounded-[2.2rem] p-8 shadow-xl backdrop-blur-md overflow-hidden" aria-labelledby="history-title">
        <div className="flex justify-between items-center mb-10">
           <div className="flex items-center space-x-3">
             <div className="w-1.5 h-6 bg-zinc-500/30 rounded-full"></div>
             <h3 id="history-title" className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-400">Activity Log</h3>
           </div>
           <div className="text-[9px] font-black text-zinc-600 uppercase tracking-widest">Showing last 25 operations</div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="text-zinc-500 text-[10px] uppercase tracking-[0.2em] border-b border-white/5">
              <tr>
                <th scope="col" className="pb-8 font-black">Date / ID</th>
                <th scope="col" className="pb-8 font-black">Type</th>
                <th scope="col" className="pb-8 font-black">Asset</th>
                <th scope="col" className="pb-8 font-black">Value</th>
                <th scope="col" className="pb-8 font-black">AI Category</th>
                <th scope="col" className="pb-8 font-black">Status</th>
                <th scope="col" className="pb-8 font-black text-right">Explorer</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/[0.03]">
              {MOCK_TRANSACTIONS.map((tx) => (
                <tr key={tx.id} className="group hover:bg-white/[0.02] transition-colors">
                  <td className="py-7">
                    <div className="text-xs font-bold text-zinc-300">{tx.date}</div>
                    <div className="text-[9px] font-mono text-zinc-600 uppercase mt-1">#TX-{tx.id.padStart(4, '0')}</div>
                  </td>
                  <td className="py-7">
                    <span className={`px-2.5 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
                      tx.type === 'Swap' ? 'bg-blue-500/10 text-blue-400' :
                      tx.type === 'Stake' ? 'bg-purple-500/10 text-purple-400' :
                      'bg-emerald-500/10 text-emerald-400'
                    }`}>
                      {tx.type}
                    </span>
                  </td>
                  <td className="py-7 font-mono text-sm font-bold text-zinc-400">{tx.asset}</td>
                  <td className="py-7">
                    <div className="text-sm font-mono font-bold text-white">{tx.amount}</div>
                    <div className="text-[9px] font-mono text-zinc-600">{tx.fiatValue}</div>
                  </td>
                  <td className="py-7">
                    <div className="flex items-center space-x-2">
                       <div className={`w-1.5 h-1.5 rounded-full ${getCategoryColor(tx.aiCategory)}`}></div>
                       <span className="text-[10px] font-black uppercase tracking-widest text-zinc-500">{tx.aiCategory}</span>
                    </div>
                  </td>
                  <td className="py-7">
                    <div className="flex items-center space-x-2">
                      {tx.status === 'Success' ? <CheckCircle2 size={14} className="text-emerald-500" /> : <AlertCircle size={14} className="text-rose-500" />}
                      <span className={`text-[10px] font-black uppercase tracking-widest ${tx.status === 'Success' ? 'text-emerald-500' : 'text-rose-500'}`}>
                        {tx.status}
                      </span>
                    </div>
                  </td>
                  <td className="py-7 text-right">
                    <button className="text-zinc-600 hover:text-emerald-500 transition-colors p-2 hover:bg-zinc-800 rounded-xl">
                      <ExternalLink size={16} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
};

export default HistoryView;

