                        aria-label={`Go to insight ${i + 1}`}
                      />
                    ))}
                  </div>
                </div>
              )}

              {/* NAV ARROWS - ONLY ON HOVER */}
              <button 
                onClick={prevInsight} 
                className="absolute -left-4 top-1/2 -translate-y-1/2 p-1 text-zinc-600 hover:text-white opacity-0 group-hover/carousel:opacity-100 transition-opacity"
