              {getPageTitle()}
            </h1>
          </div>

          {/* Center: Global Search (CMD+K) */}
          <div className={`relative max-w-md w-full mx-8 transition-all duration-300 ${searchFocused ? 'scale-[1.02]' : 'scale-100'}`}>
